WITH RECURSIVE paths AS (SELECT rowid AS ord,id,root,rtrim(replace(root,char(92),'/'),'/') AS p FROM projects), suffixes(id,pos,label) AS (SELECT id,1,p FROM paths UNION ALL SELECT s.id,s.pos+instr(substr(p.p,s.pos),'/'),substr(p.p,s.pos+instr(substr(p.p,s.pos),'/')) FROM suffixes s JOIN paths p USING(id) WHERE instr(substr(p.p,s.pos),'/')>0), distinct_suffixes AS (SELECT s.* FROM suffixes s WHERE NOT EXISTS(SELECT 1 FROM paths other WHERE other.id<>s.id AND (lower(other.p)=lower(s.label) OR substr(lower(other.p),-length(s.label)-1)='/'||lower(s.label)))), ranked AS (SELECT *,row_number() OVER(PARTITION BY id ORDER BY length(label),pos DESC) AS n FROM distinct_suffixes) SELECT p.id,p.root,coalesce(r.label,p.root) AS short FROM paths p LEFT JOIN ranked r ON r.id=p.id AND r.n=1 ORDER BY p.ord;
